def algorithm(func, dim, lb, ub, budget, rng):
    best = np.zeros(dim)
    best_value = float('inf')

    for _ in range(budget):
        candidate = lb + (ub - lb) * rng.rand(dim)

        value = func(candidate)

        if value < best_value:
            best_value = value
            best = candidate

    return best
